  function readCplBox(id) {
    if (typeof document === "undefined") return null;
    var el = document.getElementById(id);
    return el ? el.value : null;
  }
  function applyGuardToCurrent(meta) {
    var side = meta.active === "b" ? "b" : "a";
    var rec = loadCplSide(side);
    var typed = readCplBox("cpl-answer");
    if (typed != null) {
      var i = rec.qi || 0;
      if (isCrisisText(typed)) {
        rec.answers[i] = "";
        saveCplSide(side, rec);
        triggerCrisis("text");
        return "stop";
      }
      if (cplViolent(typed)) {
        rec.answers[i] = "";
        saveCplSide(side, rec);
        enterSafety(meta);
        return "stop";
      }
      rec.answers[i] = typed.slice(0, 500);
      saveCplSide(side, rec);
    }
    var note = readCplBox("cpl-note");
    if (note != null) {
      if (isCrisisText(note)) { triggerCrisis("text"); return "stop"; }
      if (cplViolent(note)) { enterSafety(meta); return "stop"; }
    }
    var niceDraft = readCplBox("cpl-nice");
    if (niceDraft != null) {
      state.cplNiceDraft = String(niceDraft).slice(0, 200);
      var niceHit = niceRisk(niceDraft);
      if (niceHit === "crisis") { state.cplNiceDraft = ""; triggerCrisis("text"); return "stop"; }
      if (niceHit === "violence") { state.cplNiceDraft = ""; enterSafety(meta); return "stop"; }
    }
    var softBox = readCplBox("cpl-soft-what");
    var softFeelBox = readCplBox("cpl-soft-feel");
    var softPickBox = readCplBox("cpl-soft-feel-pick");
    var softAskBox = readCplBox("cpl-soft-ask");
    if (softBox != null || softFeelBox != null || softPickBox != null || softAskBox != null) {
      var prevSoft = state.cplSoftDraft || blankSoftDraft();
      state.cplSoftDraft = {
        what: softClean(softBox != null ? softBox : prevSoft.what, 180),
        feel: softClean(softFeelBox != null ? softFeelBox : prevSoft.feel, 40),
        feelPick: softClean(softPickBox != null ? softPickBox : prevSoft.feelPick, 40),
        ask: softClean(softAskBox != null ? softAskBox : prevSoft.ask, 180)
      };
      var softHit = softRisk(state.cplSoftDraft);
      if (softHit === "crisis") { clearSoftDraft(); triggerCrisis("text"); return "stop"; }
      if (softHit === "violence") { clearSoftDraft(); enterSafety(meta); return "stop"; }
    }
    var toBody = readCplBox("cpl-to-body");
    var toThoughts = readCplBox("cpl-to-thoughts");
    var toVoice = readCplBox("cpl-to-voice");
    var toPhrase = readCplBox("cpl-to-phrase");
    var toOwn = readCplBox("cpl-to-own");
    var toOwn2 = readCplBox("cpl-to-own2");
    if (toBody != null || toThoughts != null || toVoice != null || toPhrase != null || toOwn != null || toOwn2 != null) {
      state.cplToDraft = readTimeoutFields();
      state.cplToDraftOwner = timeoutSide(meta);
      var toHit = timeoutRisk(state.cplToDraft);
      if (toHit === "crisis") { clearTimeoutDraft(); triggerCrisis("text"); return "stop"; }
      if (toHit === "violence") {
        if (state.cplToDraft.afraid === "yes") clearStoredTimeout(meta);
        clearTimeoutDraft();
        enterSafety(meta);
        return "stop";
      }
    }
    var repairOwn = readCplBox("cpl-pause-repair");
    if (repairOwn != null) {
      state.pauseRepairOwn = toClean(repairOwn, 160);
      if (isCrisisText(state.pauseRepairOwn)) { state.pauseRepairOwn = ""; triggerCrisis("text"); return "stop"; }
      if (cplViolent(state.pauseRepairOwn)) { state.pauseRepairOwn = ""; enterSafety(meta); return "stop"; }
    }
    var prHelped = readCplBox("cpl-pr-helped");
    var prHard = readCplBox("cpl-pr-hard");
    if (prHelped != null || prHard != null) {
      var prDraft = ensureProgressDraft(meta);
      if (prHelped != null) prDraft.helped = prClean(prHelped);
      if (prHard != null) prDraft.hard = prClean(prHard);
      var prHit = progressTextRisk(prDraft.helped + " " + prDraft.hard);
      if (prHit === "crisis") { clearProgressDraft(); enterSafety(meta, true); triggerCrisis("text"); return "stop"; }
      if (prHit === "violence") { clearProgressDraft(); enterSafety(meta); return "stop"; }
    }
    return "ok";
  }
