    isMedicationAsk: isMedicationAsk,
    isDiagnosisAsk: isDiagnosisAsk,
    respond: respond,
    scoreSum: scoreSum,
    bandPhq: bandPhq,
    bandGad: bandGad,
    programLength: programLength,
    buildProgram: buildProgram,
    selfCheckCouples: selfCheckCouples,
    cplViolent: cplViolent,
    buildCoupleSummary: buildCoupleSummary,
    selectDayIds: selectDayIds,
    todayIndex: todayIndex,
    PHQ_ITEMS: PHQ_ITEMS,
    GAD_ITEMS: GAD_ITEMS,
    TOPICS: TOPICS,
    TEMPLATES: TEMPLATES,
    norm: norm,
